  1→import { Controller, Post, Get, Body, UseGuards, Request, NotFoundException } from '@nestjs/common';
  2→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
  3→import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
  4→import { VaultService } from './vault.service';
  5→import { InitVaultDto, VaultResponseDto } from './dto/init-vault.dto';
  6→import { VaultExportDto } from './dto/vault-export.dto';
  7→import { QuotaResponseDto } from './dto/quota.dto';
  8→import { VaultConfigResponseDto } from './dto/vault-config.dto';
  9→import { RequestWithUser } from '../common/types';
 10→
 11→@ApiTags('Vault')
 12→@ApiBearerAuth()
 13→@UseGuards(JwtAuthGuard)
 14→@Controller('vault')
 15→export class VaultController {
 16→  constructor(private readonly vaultService: VaultService) {}
 17→
 18→  @Post('init')
 19→  @ApiOperation({
 20→    summary: 'Initialize user vault',
 21→    description:
 22→      'Create a new vault with encrypted keys on first sign-in. Returns 409 Conflict if vault already exists.',
 23→  })
 24→  @ApiResponse({
 25→    status: 201,
 26→    description: 'Vault initialized successfully',
 27→    type: VaultResponseDto,
 28→  })
 29→  @ApiResponse({
 30→    status: 401,
 31→    description: 'Unauthorized - JWT token required',
 32→  })
 33→  @ApiResponse({
 34→    status: 409,
 35→    description: 'Conflict - Vault already exists for this user',
 36→  })
 37→  async initializeVault(
 38→    @Request() req: RequestWithUser,
 39→    @Body() dto: InitVaultDto
 40→  ): Promise<VaultResponseDto> {
 41→    return this.vaultService.initializeVault(req.user.id, dto);
 42→  }
 43→
 44→  @Get('config')
 45→  @ApiOperation({
 46→    summary: 'Get vault configuration',
 47→    description:
 48→      'Returns application configuration including recycle bin retention period. The retention period is configurable via the RECYCLE_BIN_RETENTION_DAYS environment variable (default: 30).',
 49→  })
 50→  @ApiResponse({
 51→    status: 200,
 52→    description: 'Vault configuration',
 53→    type: VaultConfigResponseDto,
 54→  })
 55→  @ApiResponse({
 56→    status: 401,
 57→    description: 'Unauthorized - JWT token required',
 58→  })
 59→  getConfig(): VaultConfigResponseDto {
 60→    return this.vaultService.getConfig();
 61→  }
 62→
 63→  @Get('export')
 64→  @ApiOperation({
 65→    summary: 'Export vault for independent recovery',
 66→    description:
 67→      'Returns the minimal vault data needed for independent recovery: root IPNS name, encrypted root keys, and derivation hints.',
 68→  })
 69→  @ApiResponse({
 70→    status: 200,
 71→    description: 'Vault export data',
 72→    type: VaultExportDto,
 73→  })
 74→  @ApiResponse({
 75→    status: 401,
 76→    description: 'Unauthorized - JWT token required',
 77→  })
 78→  @ApiResponse({
 79→    status: 404,
 80→    description: 'Not Found - Vault does not exist',
 81→  })
 82→  async exportVault(@Request() req: RequestWithUser): Promise<VaultExportDto> {
 83→    return this.vaultService.getExportData(req.user.id);
 84→  }
 85→
 86→  @Get()
 87→  @ApiOperation({
 88→    summary: 'Get user vault',
 89→    description: 'Retrieve the vault for the authenticated user.',
 90→  })
 91→  @ApiResponse({
 92→    status: 200,
 93→    description: 'Vault retrieved successfully',
 94→    type: VaultResponseDto,
 95→  })
 96→  @ApiResponse({
 97→    status: 401,
 98→    description: 'Unauthorized - JWT token required',
 99→  })
100→  @ApiResponse({
101→    status: 404,
102→    description: 'Not Found - Vault does not exist',
103→  })
104→  async getVault(@Request() req: RequestWithUser): Promise<VaultResponseDto> {
105→    const vault = await this.vaultService.findVault(req.user.id);
106→    if (!vault) {
107→      throw new NotFoundException('Vault not found');
108→    }
109→    return vault;
110→  }
111→
112→  @Get('quota')
113→  @ApiOperation({
114→    summary: 'Get storage quota',
115→    description: 'Get current storage usage and limits. Limit is 500 MiB (524,288,000 bytes).',
116→  })
117→  @ApiResponse({
118→    status: 200,
119→    description: 'Quota retrieved successfully',
120→    type: QuotaResponseDto,
121→  })
122→  @ApiResponse({
123→    status: 401,
124→    description: 'Unauthorized - JWT token required',
125→  })
126→  async getQuota(@Request() req: RequestWithUser): Promise<QuotaResponseDto> {
127→    return this.vaultService.getQuota(req.user.id);
128→  }
129→}
