 31→export async function createAndPublishIpnsRecord(params: {
 32→  ipnsPrivateKey: Uint8Array;
 33→  ipnsName: string;
 34→  metadataCid: string;
 35→  sequenceNumber: bigint;
 36→  encryptedIpnsPrivateKey?: string;
 37→  keyEpoch?: number;
 38→  expectedSequenceNumber?: string;
 39→}): Promise<{ success: boolean; sequenceNumber: bigint }> {
 40→  // 1. Create IPNS record pointing to /ipfs/{metadataCid}
 41→  // 24 hour lifetime (will be republished by TEE every 3 hours)
 42→  const record = await createIpnsRecord(
 43→    params.ipnsPrivateKey,
 44→    `/ipfs/${params.metadataCid}`,
 45→    params.sequenceNumber,
 46→    24 * 60 * 60 * 1000 // 24 hours in ms
 47→  );
 48→
 49→  // 2. Marshal to bytes for transport
 50→  const recordBytes = marshalIpnsRecord(record);
 51→
 52→  // 3. Base64 encode for API transmission
 53→  const recordBase64 = btoa(String.fromCharCode(...recordBytes));
 54→
 55→  // 4. Call backend API to relay to IPFS network
 56→  const response = await ipnsControllerPublishRecord({
 57→    ipnsName: params.ipnsName,
 58→    record: recordBase64,
 59→    metadataCid: params.metadataCid,
 60→    encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
