 65→/// IPNS publish request body matching the backend PublishIpnsDto.
 66→#[derive(Debug, serde::Serialize)]
 67→#[serde(rename_all = "camelCase")]
 68→pub struct IpnsPublishRequest {
 69→    /// IPNS name (k51... CIDv1 format).
 70→    pub ipns_name: String,
 71→    /// Base64-encoded marshaled IPNS record (protobuf bytes).
 72→    pub record: String,
 73→    /// CID of the encrypted metadata this record points to.
 74→    pub metadata_cid: String,
 75→    /// Hex-encoded ECIES-wrapped Ed25519 private key for TEE republishing
 76→    /// (only required on first publish for a new folder).
 77→    #[serde(skip_serializing_if = "Option::is_none")]
 78→    pub encrypted_ipns_private_key: Option<String>,
 79→    /// TEE key epoch (required with encrypted_ipns_private_key).
 80→    #[serde(skip_serializing_if = "Option::is_none")]
 81→    pub key_epoch: Option<u32>,
 82→    /// Expected sequence number for optimistic concurrency control.
 83→    /// If set, the server returns 409 Conflict if the current sequence
 84→    /// does not match. Omit to perform an unconditional publish.
 85→    #[serde(skip_serializing_if = "Option::is_none")]
 86→    pub expected_sequence_number: Option<String>,
 87→}
 88→
 89→/// Publish a signed IPNS record via the backend.
 90→///
 91→/// POST /ipns/publish with the signed record. The backend relays
 92→/// to the delegated routing service and tracks the folder for TEE republishing.
 93→///
 94→/// Returns `PublishResult::Success` on 2xx, `PublishResult::Conflict`
 95→/// on 409 (another device published a higher sequence), or `Err` on
 96→/// other errors.
 97→pub async fn publish_ipns(
 98→    client: &ApiClient,
 99→    request: &IpnsPublishRequest,
100→) -> Result<PublishResult, String> {
101→    let resp = client
102→        .authenticated_post("/ipns/publish", request)
103→        .await
104→        .map_err(|e| format!("IPNS publish failed: {}", e))?;
105→
106→    if resp.status().as_u16() == 409 {
107→        // Parse conflict response body: { currentSequenceNumber: "..." }
108→        let body: serde_json::Value = resp
109→            .json()
110→            .await
111→            .map_err(|e| format!("409 Conflict but failed to parse body: {}", e))?;
112→        let current_seq = body["currentSequenceNumber"]
113→            .as_str()
114→            .ok_or_else(|| {
115→                format!(
116→                    "409 Conflict but missing currentSequenceNumber in response: {}",
117→                    body
118→                )
119→            })?
120→            .to_string();
121→        return Ok(PublishResult::Conflict {
122→            current_sequence_number: current_seq,
123→        });
124→    }
125→
126→    if !resp.status().is_success() {
127→        let status = resp.status();
128→        let body = resp.text().await.unwrap_or_default();
129→        return Err(format!("IPNS publish failed ({}): {}", status, body));
130→    }
131→
132→    Ok(PublishResult::Success)
133→}
