71→/// Unpin content from IPFS via the backend.
72→///
73→/// POST /ipfs/unpin with `{ cid }`. Fire-and-forget on delete
74→/// (matches web app pattern -- 404 treated as success).
75→pub async fn unpin_content(client: &ApiClient, cid: &str) -> Result<(), String> {
76→    #[derive(serde::Serialize)]
77→    struct UnpinRequest<'a> {
78→        cid: &'a str,
79→    }
80→
81→    let resp = client
82→        .authenticated_post("/ipfs/unpin", &UnpinRequest { cid })
83→        .await
84→        .map_err(|e| format!("IPFS unpin failed: {}", e))?;
85→
86→    // 404 is success (already unpinned -- idempotent behavior)
87→    if resp.status().as_u16() == 404 || resp.status().is_success() {
88→        Ok(())
89→    } else {
90→        let status = resp.status();
91→        let body = resp.text().await.unwrap_or_default();
92→        Err(format!("IPFS unpin failed ({}): {}", status, body))
93→    }
94→}
